# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.92.0/ankra-cli-darwin-arm64"
      sha256 "3f660f9035a07a606be275cd63d98c29e2a847b12583f8289c18554b54676e66"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.92.0/ankra-cli-darwin-amd64"
      sha256 "bb61813893cbe48f49135c65fbf81955b692780c5893396c2a167db7ea8c263f"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.92.0/ankra-cli-linux-arm64"
      sha256 "bf1a2207ea28b176c9a625db0d8c41d096330a5ae12c62254f968f01d19f8cab"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.92.0/ankra-cli-linux-amd64"
